@import "@fontsource-variable/inter/opsz.css";
@import "@fontsource-variable/newsreader";
@import "@fontsource-variable/source-code-pro";

/* Light (the faithful mode): a white page inside two hairlines, near-black text with slate
   grey second clauses, #fafafa / #f2f3f4 panels, a near-black primary button, one blue for
   badges, rules and the growth line, and a lavender wash as the glow. The middle band, the
   closing CTA and the footer use the .dark values below (those blocks force .dark). */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.215 0.004 265);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.215 0.004 265);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.215 0.004 265);
  --primary: oklch(0.24 0.005 265);
  --primary-foreground: oklch(0.975 0.002 265);
  --secondary: oklch(0.963 0.002 265);
  --secondary-foreground: oklch(0.215 0.004 265);
  --muted: oklch(0.984 0.001 265);
  --muted-foreground: oklch(0.555 0.018 262);
  --accent: oklch(0.963 0.002 265);
  --accent-foreground: oklch(0.2 0.004 265);
  --destructive: oklch(0.63 0.21 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.93 0.004 265);
  --input: oklch(0.865 0.007 265);
  --ring: oklch(0.57 0.2 262);
  --highlight: oklch(0.55 0.2 262);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.78 0.1 278);
  --chart-1: oklch(0.57 0.2 262);
  --chart-2: oklch(0.72 0.15 158);
  --chart-3: oklch(0.78 0.16 75);
  --chart-4: oklch(0.65 0.21 25);
  --chart-5: oklch(0.6 0.2 300);
  --sidebar: oklch(0.984 0.001 265);
  --sidebar-foreground: oklch(0.215 0.004 265);
  --sidebar-primary: oklch(0.24 0.005 265);
  --sidebar-primary-foreground: oklch(0.975 0.002 265);
  --sidebar-accent: oklch(0.963 0.002 265);
  --sidebar-accent-foreground: oklch(0.2 0.004 265);
  --sidebar-border: oklch(0.93 0.004 265);
  --sidebar-ring: oklch(0.57 0.2 262);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Source Code Pro Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* the quote's text serif; attio blocks fall back to the display face without it */
  --attio-serif: "Newsreader Variable", ui-serif, Georgia, serif;
  --radius: 0.5rem;
  --page-width: 87rem;
  --page-gutter: clamp(1rem, 0.4rem + 1.5vw, 1.5rem);
  --section-y: clamp(5.5rem, 4rem + 4vw, 9.5rem);
}

/* Dark: the #111 band with pinstripes, #1c1d1f raised tiles, white headings over a cool
   slate grey, a graphite button, a pale blue on navy for badges. */
.dark {
  --background: oklch(0.172 0 0);
  --foreground: oklch(0.975 0.002 265);
  --card: oklch(0.215 0.004 265);
  --card-foreground: oklch(0.975 0.002 265);
  --popover: oklch(0.215 0.004 265);
  --popover-foreground: oklch(0.975 0.002 265);
  --primary: oklch(0.32 0.008 265);
  --primary-foreground: oklch(0.975 0.002 265);
  --secondary: oklch(0.235 0.005 265);
  --secondary-foreground: oklch(0.975 0.002 265);
  --muted: oklch(0.2 0.003 265);
  --muted-foreground: oklch(0.66 0.02 262);
  --accent: oklch(0.26 0.006 265);
  --accent-foreground: oklch(0.975 0.002 265);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 9%);
  --input: oklch(1 0 0 / 16%);
  --ring: oklch(0.7 0.14 262);
  --highlight: oklch(0.8 0.09 262);
  --highlight-foreground: oklch(0.2 0.03 262);
  --glow: oklch(0.7 0.14 262);
  --chart-1: oklch(0.65 0.18 262);
  --chart-2: oklch(0.74 0.15 158);
  --chart-3: oklch(0.8 0.15 75);
  --chart-4: oklch(0.68 0.19 25);
  --chart-5: oklch(0.68 0.17 300);
  --sidebar: oklch(0.2 0.003 265);
  --sidebar-foreground: oklch(0.975 0.002 265);
  --sidebar-primary: oklch(0.65 0.18 262);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.26 0.006 265);
  --sidebar-accent-foreground: oklch(0.975 0.002 265);
  --sidebar-border: oklch(1 0 0 / 9%);
  --sidebar-ring: oklch(0.7 0.14 262);
}
